dataSample.sql:
CREATE TABLE IF NOT EXISTS `PREFIX_leoelements_category` ( `id_leoelements_category` int(11) NOT NULL AUTO_INCREMENT, `clist_key` varchar(255) DEFAULT NULL, `name` varchar(255) DEFAULT NULL, `class` varchar(255) DEFAULT NULL, `params` text DEFAULT NULL, `type` tinyint(1) DEFAULT NULL, `active` tinyint(1) DEFAULT NULL, `active_mobile` tinyint(1) DEFAULT NULL, `active_tablet` tinyint(1) DEFAULT NULL, PRIMARY KEY (`id_leoelements_category`) USING BTREE ) ENGINE=ENGINE_TYPE AUTO_INCREMENT=1 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `PREFIX_leoelements_category_shop` ( `id_leoelements_category` int(11) NOT NULL AUTO_INCREMENT, `id_shop` int(10) unsigned NOT NULL, `active` tinyint(1) DEFAULT NULL, `active_mobile` tinyint(1) DEFAULT NULL, `active_tablet` tinyint(1) DEFAULT NULL, PRIMARY KEY (`id_leoelements_category`,`id_shop`) USING BTREE ) ENGINE=ENGINE_TYPE AUTO_INCREMENT=1 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `PREFIX_leoelements_contents` ( `id_leoelements_contents` int(11) NOT NULL AUTO_INCREMENT, `name` varchar(255) DEFAULT NULL, `type` varchar(255) DEFAULT NULL, `content_key` varchar(255) DEFAULT NULL, `hook` varchar(255) DEFAULT NULL, `active` tinyint(1) DEFAULT NULL, PRIMARY KEY (`id_leoelements_contents`) USING BTREE ) ENGINE=ENGINE_TYPE AUTO_INCREMENT=1 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `PREFIX_leoelements_contents_lang` ( `id_leoelements_contents` int(11) NOT NULL, `id_lang` int(11) NOT NULL, `content` longtext DEFAULT NULL, `content_autosave` longtext DEFAULT NULL, PRIMARY KEY (`id_leoelements_contents`,`id_lang`) USING BTREE ) ENGINE=ENGINE_TYPE DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `PREFIX_leoelements_contents_shop` ( `id_leoelements_contents` int(11) NOT NULL, `id_shop` int(10) unsigned NOT NULL, `active` tinyint(1) DEFAULT NULL, PRIMARY KEY (`id_leoelements_contents`,`id_shop`) USING BTREE ) ENGINE=ENGINE_TYPE DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `PREFIX_leoelements_fonts` ( `id_leoelements_fonts` int(11) NOT NULL AUTO_INCREMENT, `name` varchar(50) NOT NULL, `type` tinyint(1) NOT NULL, `font_family` varchar(50) NOT NULL, `font_style` varchar(50) DEFAULT 'normal', `font_weight` int(11) DEFAULT 400, `file` varchar(255) NOT NULL, PRIMARY KEY (`id_leoelements_fonts`) USING BTREE ) ENGINE=ENGINE_TYPE DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `PREFIX_leoelements_meta` ( `id_leoelements_meta` int(11) NOT NULL AUTO_INCREMENT, `id` int(10) unsigned NOT NULL, `name` varchar(255) DEFAULT NULL, `value` longtext DEFAULT NULL, PRIMARY KEY (`id_leoelements_meta`) USING BTREE ) ENGINE=ENGINE_TYPE AUTO_INCREMENT=1 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `PREFIX_leoelements_positions` ( `id_leoelements_positions` int(11) NOT NULL AUTO_INCREMENT, `name` varchar(255) NOT NULL, `position` varchar(255) NOT NULL, `position_key` varchar(255) NOT NULL, `params` text DEFAULT NULL, PRIMARY KEY (`id_leoelements_positions`) USING BTREE ) ENGINE=ENGINE_TYPE AUTO_INCREMENT=1 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `PREFIX_leoelements_product_list` ( `id_leoelements_product_list` int(11) NOT NULL AUTO_INCREMENT, `plist_key` varchar(255) DEFAULT NULL, `name` varchar(255) DEFAULT NULL, `class` varchar(255) DEFAULT NULL, `params` text DEFAULT NULL, `type` tinyint(1) DEFAULT NULL, `active` tinyint(1) DEFAULT NULL, `active_mobile` tinyint(1) DEFAULT NULL, `active_tablet` tinyint(1) DEFAULT NULL, PRIMARY KEY (`id_leoelements_product_list`) USING BTREE ) ENGINE=ENGINE_TYPE AUTO_INCREMENT=1 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `PREFIX_leoelements_product_list_shop` ( `id_leoelements_product_list` int(11) NOT NULL AUTO_INCREMENT, `id_shop` int(10) unsigned NOT NULL, `active` tinyint(1) DEFAULT NULL, `active_mobile` tinyint(1) DEFAULT NULL, `active_tablet` tinyint(1) DEFAULT NULL, PRIMARY KEY (`id_leoelements_product_list`,`id_shop`) USING BTREE ) ENGINE=ENGINE_TYPE AUTO_INCREMENT=1 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `PREFIX_leoelements_products` ( `id_leoelements_products` int(11) NOT NULL AUTO_INCREMENT, `plist_key` varchar(255) DEFAULT NULL, `name` varchar(255) DEFAULT NULL, `class_detail` varchar(255) DEFAULT NULL, `url_img_preview` varchar(255) DEFAULT NULL, `params` text DEFAULT NULL, `type` tinyint(1) DEFAULT NULL, `active` tinyint(1) DEFAULT NULL, `active_mobile` tinyint(1) DEFAULT NULL, `active_tablet` tinyint(1) DEFAULT NULL, PRIMARY KEY (`id_leoelements_products`) USING BTREE ) ENGINE=ENGINE_TYPE AUTO_INCREMENT=1 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `PREFIX_leoelements_products_shop` ( `id_leoelements_products` int(11) NOT NULL AUTO_INCREMENT, `id_shop` int(10) unsigned NOT NULL, `active` tinyint(1) DEFAULT NULL, `active_mobile` tinyint(1) DEFAULT NULL, `active_tablet` tinyint(1) DEFAULT NULL, PRIMARY KEY (`id_leoelements_products`,`id_shop`) USING BTREE ) ENGINE=ENGINE_TYPE AUTO_INCREMENT=1 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `PREFIX_leoelements_profiles` ( `id_leoelements_profiles` int(11) NOT NULL AUTO_INCREMENT, `name` varchar(255) DEFAULT NULL, `group_box` varchar(255) DEFAULT NULL, `profile_key` varchar(255) DEFAULT NULL, `page` varchar(255) DEFAULT NULL, `params` text DEFAULT NULL, `header` varchar(255) DEFAULT NULL, `content` varchar(255) DEFAULT NULL, `footer` varchar(255) DEFAULT NULL, `product` varchar(255) DEFAULT NULL, `active` tinyint(1) DEFAULT NULL, `active_mobile` tinyint(1) DEFAULT NULL, `active_tablet` tinyint(1) DEFAULT NULL, PRIMARY KEY (`id_leoelements_profiles`) USING BTREE ) ENGINE=ENGINE_TYPE AUTO_INCREMENT=1 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `PREFIX_leoelements_profiles_lang` ( `id_leoelements_profiles` int(11) NOT NULL AUTO_INCREMENT, `id_lang` int(10) unsigned NOT NULL, `friendly_url` varchar(255) DEFAULT NULL, `meta_title` varchar(255) DEFAULT NULL, `meta_description` varchar(255) DEFAULT NULL, `meta_keywords` varchar(255) DEFAULT NULL, PRIMARY KEY (`id_leoelements_profiles`,`id_lang`) USING BTREE ) ENGINE=ENGINE_TYPE AUTO_INCREMENT=1 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `PREFIX_leoelements_profiles_shop` ( `id_leoelements_profiles` int(11) NOT NULL AUTO_INCREMENT, `id_shop` int(10) unsigned NOT NULL, `active` tinyint(1) DEFAULT NULL, `active_mobile` tinyint(1) DEFAULT NULL, `active_tablet` tinyint(1) DEFAULT NULL, PRIMARY KEY (`id_leoelements_profiles`,`id_shop`) USING BTREE ) ENGINE=ENGINE_TYPE AUTO_INCREMENT=1 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `PREFIX_leoelements_related` ( `id_leoelements_related` int(11) NOT NULL AUTO_INCREMENT, `id_post` int(10) unsigned NOT NULL, `post_type` varchar(255) NOT NULL, `key_related` varchar(255) NOT NULL, PRIMARY KEY (`id_leoelements_related`) USING BTREE ) ENGINE=ENGINE_TYPE AUTO_INCREMENT=1 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `PREFIX_leoelements_related_shop` ( `id_leoelements_related` int(11) NOT NULL, `id_shop` int(11) NOT NULL, PRIMARY KEY (`id_leoelements_related`,`id_shop`) USING BTREE ) ENGINE=ENGINE_TYPE DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `PREFIX_leoelements_revisions` ( `id_leoelements_revisions` int(11) NOT NULL AUTO_INCREMENT, `id_post` int(10) unsigned NOT NULL, `id_lang` int(10) unsigned NOT NULL, `id_employee` int(10) unsigned NOT NULL, `content` longtext DEFAULT NULL, `page_settings` longtext DEFAULT NULL, `date_add` datetime NOT NULL, PRIMARY KEY (`id_leoelements_revisions`,`id_post`,`id_lang`) USING BTREE ) ENGINE=ENGINE_TYPE DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `PREFIX_leoelements_template` ( `id_leoelements_template` int(11) NOT NULL AUTO_INCREMENT, `id_employee` int(10) unsigned NOT NULL, `title` varchar(40) NOT NULL, `type` varchar(40) NOT NULL, `content` longtext DEFAULT NULL, `page_settings` longtext DEFAULT NULL, `date_add` datetime NOT NULL, PRIMARY KEY (`id_leoelements_template`) USING BTREE ) ENGINE=ENGINE_TYPE AUTO_INCREMENT=1 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;
